    public static AssembledScriptDefinition? Resolve(string? build, string? baseCardId,
        IReadOnlyDictionary<string, string> tags, IReadOnlyDictionary<string, CardRecord> cards)
    {
        ArgumentNullException.ThrowIfNull(tags); ArgumentNullException.ThrowIfNull(cards);
        if (build != Build || baseCardId is null || !AssembledCardText.RequiresCustomText(tags) ||
            !Definitions.TryGetValue(baseCardId, out var body) || !body.MinionBase || !Audited(baseCardId, body, cards)) return null;
        var text = AssembledCardText.Resolve(build, baseCardId, tags, cards);
        if (!text.IsResolved || text.IsOffer || text.EffectiveText is null || text.FirstHalfDbfId is not { } first ||
            text.SecondHalfDbfId is not { } second || first is < 0 or 1 || second is < 0 or 1 ||
            text.TriggerCardId is not { } triggerId || text.EffectCardId is not { } effectId ||
            !Definitions.TryGetValue(triggerId, out var trigger) || !trigger.BattlecryTrigger ||
            !Definitions.TryGetValue(effectId, out var effect) || !effect.HandBuffEffect ||
            !Audited(triggerId, trigger, cards) || !Audited(effectId, effect, cards)) return null;
        return new(baseCardId, triggerId, effectId, first, second, text.EffectiveText, HandBuffScriptKey,
            body.Fingerprint, trigger.Fingerprint, effect.Fingerprint);
    }

    private static bool Audited(string id, Definition definition, IReadOnlyDictionary<string, CardRecord> cards)
    {
        if (!cards.TryGetValue(id, out var card) || card is null || card.Id != id || card.DbfId != definition.DbfId ||
            card.Type != definition.Type || card.RawJson is not { Length: > 0 and <= 65536 }) return false;
        try
        {
            using var document = JsonDocument.Parse(card.RawJson);
            return NativeCardDefinitions.RecordMatchesRaw(card, document.RootElement) &&
                NativeCardDefinitions.CanonicalHash(document.RootElement) == definition.Fingerprint;
        }
        catch (Exception error) when (error is JsonException or InvalidOperationException or KeyNotFoundException or FormatException or OverflowException or ArgumentException)
        { return false; }
    }
